# Now let me check the actual GTL traces to understand routing progress
with open('Gerber_TopLayer.GTL') as f:
    gtl = f.read()

# Count different aperture usage in trace section (after pad end)
pad_end = -1
lines = gtl.split('\\n')
for i, line in enumerate(lines):
    if 'G04 Pad End' in line:
        pad_end = i
        break

# Extract trace aperture usage
trace_apertures = {}
if pad_end > 0:
    for i in range(pad_end+1, len(lines)):
        line = lines[i]
        if line.startswith('G54D'):
            ap_num = int(line.split('D')[1].split('*')[0])
            trace_apertures[ap_num] = trace_apertures.get(ap_num, 0) + 1

# Get aperture definitions
apertures = {}
for line in lines:
    if line.startswith('%ADD'):
        # %ADD10C,0.3*% etc
        parts = line.rstrip('*%').split('ADD')
        if len(parts) >= 2:
            num_and_def = parts[1]
            # num is first 2 chars
            try:
                num = int(num_and_def[:2])
                ap_def = num_and_def[2:]
                apertures[num] = ap_def
            except:
                pass

print('=== Top Layer trace apertures used ===')
for num in sorted(trace_apertures.keys()):
    count = trace_apertures[num]
    ap_def = apertures.get(num, 'unknown')
    print(f'  D{num} ({ap_def}): {count} uses')

