# Now let's do a comprehensive check of all other differences between 06-16 and 06-18 netlists
# Focus on: FPC2 (touch), power nets, and any other changes

# Read the new netlist text
with open('/home/lijian/project/rv1126b/rv1126bsportCam/hardware/Netlist_core_board_module_2026-06-18.tel') as f:
    new_text = f.read()

# Parse nets from new netlist
new_nets = {}
current_net = None
current_pins = []

for line in new_text.split('\n'):
    line = line.strip().rstrip(';').rstrip(',')
    if line.startswith(\"'\") and ';' in line:
        # New net definition
        if current_net and current_pins:
            new_nets[current_net] = current_pins
        parts = line.split(\"'\", 2)
        net_name = parts[1]
        rest = parts[2].strip()
        if rest.startswith(';'):
            rest = rest[1:].strip()
        pins = [p.strip() for p in rest.split() if p.strip()]
        current_net = net_name
        current_pins = pins
    elif current_net and line and not line.startswith('\$'):
        # Continuation or another net without quotes
        pins = [p.strip() for p in line.split() if p.strip() and not p.startswith('\$')]
        if pins:
            current_pins.extend(pins)
        else:
            if current_net and current_pins:
                new_nets[current_net] = current_pins
            current_net = None
            current_pins = []

if current_net and current_pins:
    new_nets[current_net] = current_pins

